def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter

    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]
    directions = [(1, 1), (1, -1), (-1, 1), (-1, -1)]

    # Extend every diagonal run of at least two matching non-background cells
    # in both directions, continuing until the grid edge.
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == background:
                continue
            for dr, dc in directions:
                nr, nc = r + dr, c + dc
                if not (0 <= nr < h and 0 <= nc < w) or grid[nr][nc] != color:
                    continue
                # Only start from the first cell of a run in this direction.
                pr, pc = r - dr, c - dc
                if 0 <= pr < h and 0 <= pc < w and grid[pr][pc] == color:
                    continue
                rr, cc = r - dr, c - dc
                while 0 <= rr < h and 0 <= cc < w:
                    if out[rr][cc] == background:
                        out[rr][cc] = color
                    rr -= dr
                    cc -= dc
                rr, cc = nr, nc
                while 0 <= rr < h and 0 <= cc < w and grid[rr][cc] == color:
                    rr += dr
                    cc += dc
                while 0 <= rr < h and 0 <= cc < w:
                    if out[rr][cc] == background:
                        out[rr][cc] = color
                    rr += dr
                    cc += dc
    return out
